# dark-patterns: the real page clippings for the talking-head edit, shorts, teaser and film (crops only, nothing altered).
# Base set from the directions (film/stills/directions/_tools/clips.py) + new captures 2026-11-02 (FTC Amazon, UCPD Annex I,
# CRD Art 22, CMS on the DFA, deceptive.design). Writes film/assets/src/clips.js (const CLIPS) and the PNGs.
import json, os
from PIL import Image
S = os.path.dirname(os.path.abspath(__file__)).replace('talking-head/tools', 'film/assets/src')
base = json.load(open(os.path.join(S, '..', '..', 'stills', 'directions', '_src', 'clips', 'clips.json')))
def crop(name, img, box, hl, source, date, url):
    Image.open(os.path.join(S, img)).convert('RGB').crop(box).save(os.path.join(S, name + '.png'))
    base[name] = {'w': box[2] - box[0], 'h': box[3] - box[1], 'hl': hl, 'source': source, 'date': date, 'url': url}
FTCA = 'https://www.ftc.gov/news-events/news/press-releases/2026/09/ftc-announces-additional-payments-consumers-stemming-ftcs-amazon-prime-settlement'
crop('ftc-amazon-q1', 'ftc-amazon__2-5-billion.png', (120, 970, 770, 1068), [[198, 2, 282, 44], [124, 52, 512, 44]], 'FTC press release', '17 Sep 2026', FTCA)
crop('ftc-amazon-q2', 'ftc-amazon__2-5-billion.png', (120, 1100, 1180, 1252), [[220, 0, 350, 46], [262, 52, 180, 46], [640, 102, 300, 46]], 'FTC press release', '17 Sep 2026', FTCA)
crop('ucpd-7', 'ucpd-annex__very-limited-time.png', (470, 768, 1910, 888), [[90, 6, 668, 42]], 'Unfair Commercial Practices Directive 2005, Annex I', 'legislation.gov.uk', 'https://www.legislation.gov.uk/eudr/2005/29/annex/I/adopted')
crop('crd-22', 'crd-22__default-options.png', (480, 700, 1905, 850), [[372, 76, 668, 40], [520, 113, 392, 38]], 'Consumer Rights Directive, Article 22', 'legislation.gov.uk', 'https://www.legislation.gov.uk/eudr/2011/83/article/22')
crop('cms-dfa', 'cms-dfa__11-november-2026.png', (690, 742, 1800, 856), [[205, 38, 608, 40]], 'CMS law firm', '19 Oct 2026', 'https://cms.law/en/aut/legal-updates/inside-the-eu-s-planned-digital-fairness-act-digital-design-subscription-traps-and-influencer-marketing')
crop('dd-cancel', 'dd-types__hard-to-cancel.png', (184, 746, 946, 1062), [], 'deceptive.design/types', 'Harry Brignull', 'https://deceptive.design/types')
crop('dd-sneak', 'dd-types__sneaking.png', (184, 498, 946, 814), [], 'deceptive.design/types', 'Harry Brignull', 'https://deceptive.design/types')
json.dump(base, open(os.path.join(S, 'clips.json'), 'w'), indent=1)
open(os.path.join(S, 'clips.js'), 'w').write('/* generated by talking-head/tools/clips2.py: real page clippings (crops only) + highlight boxes in clip px */\nconst CLIPS = ' + json.dumps(base) + ';\n')
print(sorted(base))
